import { Worker } from 'node:worker_threads';
function main(): void {
  const ia = new Int32Array(new SharedArrayBuffer(8));
  const worker = new Worker(`
    const { parentPort, workerData } = require('node:worker_threads');
    const ia = new Int32Array(workerData);
    const keep = setTimeout(() => {}, 300);
    Atomics.waitAsync(ia, 0, 0).value.then((v) => { parentPort.postMessage('got ' + v); clearTimeout(keep); });
    parentPort.postMessage('ready');
  `, { eval: true, workerData: ia.buffer });
  worker.on('message', (m: any) => {
    if (m === 'ready') {
      setTimeout(() => console.log('notify', Atomics.notify(ia, 0, 1)), 50);
    } else {
      console.log('main saw', m);
      void worker.terminate();
    }
  });
}
